if(msg.requestBody&&typeof msg.requestBody==='object'){msg.payload=JSON.parse(JSON.stringify(msg.requestBody));}
if(!msg.payload||typeof msg.payload!=='object'||!Array.isArray(msg.payload.messages)){node.error(`Payload AI tidak valid untuk ${name}.`,msg);return null;}
msg.payload.model=p.model;
return msg;

const status=Number(msg.statusCode||0);
const content=String(msg.payload?.choices?.[0]?.message?.content||'').trim();
const ok=status>=200 && status<300 && !!content;
if(ok){msg.aiProviderUsed=msg.aiProvider;return [msg,null,null];}
const body=typeof msg.payload==='string'?msg.payload:JSON.stringify(msg.payload);
msg.aiLastError=`${msg.aiProvider||'provider'} HTTP ${status||'ERR'}: ${(body||'request failed').slice(0,300)}`;
msg.aiErrors=Array.isArray(msg.aiErrors)?msg.aiErrors:[];
msg.aiErrors.push(msg.aiLastError);
const order=String(env.get('AI_PROVIDER_ORDER')||'groq,gemini,openrouter').split(',').map(s=>s.trim().toLowerCase()).filter(Boolean);
const available=order.filter(p=>{
 if(p==='groq') return !!env.get('GROQ_API_KEY');
 if(p==='gemini') return !!env.get('GEMINI_API_KEY');
 if(p==='openrouter') return !!env.get('OPENROUTER_API_KEY');
 return false;
});
msg.aiAttempt=(Number.isInteger(msg.aiAttempt)?msg.aiAttempt:0)+1;
if(msg.aiAttempt<available.length) return [null,msg,null];
msg.aiText='Semua AI provider gagal.\n'+(Array.isArray(msg.aiErrors)&&msg.aiErrors.length?msg.aiErrors.join('\n'):msg.aiLastError);
return [null,null,msg];

const o=msg.originalMessage||{};
const src=(o.reply_to_message&&(o.reply_to_message.photo||o.reply_to_message.document))||o.photo||o.document;
let fileId=null;
if(src){
 if(Array.isArray(src)&&src.length){fileId=src[src.length-1].file_id;}
 else if(src.file_id){fileId=src.file_id;}
}
if(!fileId){
 msg.payload={chatId:msg.chatId,type:'message',content:'Kirim gambar dengan caption <code>/sticker</code>, atau reply gambar dengan <code>/sticker</code>.',options:{parse_mode:'HTML'}};
 return [null,msg];
}
const token=env.get('TELEGRAM_BOT_TOKEN');
if(!token){msg.payload={chatId:msg.chatId,type:'message',content:'TELEGRAM_BOT_TOKEN belum diatur di .env.',options:{parse_mode:'HTML'}};return [null,msg];}
msg.stickerFileId=fileId;
msg.method='GET';
msg.url='https://api.telegram.org/bot'+token+'/getFile?file_id='+encodeURIComponent(fileId);
return [msg,null];

const r=msg.payload&&msg.payload.result;
if(!msg.payload||!msg.payload.ok||!r||!r.file_path){
 msg.payload={chatId:msg.chatId,type:'message',content:'Gagal mengambil file dari Telegram.',options:{parse_mode:'HTML'}};
 return [null,msg];
}
const token=env.get('TELEGRAM_BOT_TOKEN');
msg.method='GET';
msg.url='https://api.telegram.org/file/bot'+token+'/'+r.file_path;
return [msg,null];

if(!Buffer.isBuffer(msg.payload)||!msg.payload.length){
 msg.payload={chatId:msg.chatId,type:'message',content:'Download gambar gagal.',options:{parse_mode:'HTML'}};
 return msg;
}
const userId=msg.senderId||msg.chatId;
const setName='inote_'+userId+'_by_integrator_app_bot';
const setTitle='Stiker Integrator '+(msg.senderName||'');
const reply=async(text)=>{msg.payload={chatId:msg.chatId,type:'message',content:text,options:{parse_mode:'HTML',link_preview_options:{is_disabled:true}}};return msg;};
try{
 const {data,info}=await sharp(msg.payload,{failOn:'none'}).ensureAlpha().raw().toBuffer({resolveWithObject:true});
 const W=info.width,H=info.height,ch=info.channels;
 const bg=new Uint8Array(W*H);
 const q=new Int32Array(W*H);
 let qh=0,qt=0;
 const push=(i)=>{if(!bg[i]){bg[i]=1;q[qt++]=i;}};
 const edge=[];
 for(let x=0;x<W;x++){edge.push(x,(H-1)*W+x);}
 for(let y=0;y<H;y++){edge.push(y*W,y*W+W-1);}
 let er=0,eg=0,eb=0;
 for(let k=0;k<edge.length;k++){const i=edge[k];er+=data[i*ch];eg+=data[i*ch+1];eb+=data[i*ch+2];}
 er/=edge.length;eg/=edge.length;eb/=edge.length;
 let near=0;
 for(let k=0;k<edge.length;k++){const i=edge[k];if(Math.abs(data[i*ch]-er)+Math.abs(data[i*ch+1]-eg)+Math.abs(data[i*ch+2]-eb)<=75)near++;}
 const solid=near/edge.length>=0.85;
 if(solid){
  for(let k=0;k<edge.length;k++)push(edge[k]);
  while(qh<qt){
   const i=q[qh++];
   const cand=(j)=>{if(bg[j])return;if(Math.abs(data[j*ch]-er)+Math.abs(data[j*ch+1]-eg)+Math.abs(data[j*ch+2]-eb)<=75)push(j);};
   const iy=(i/W)|0,ix=i-iy*W;
   if(ix>0)cand(i-1);
   if(ix<W-1)cand(i+1);
   if(iy>0)cand(i-W);
   if(iy<H-1)cand(i+W);
  }
  for(let i=0;i<W*H;i++)if(bg[i])data[i*ch+3]=0;
  for(let i=0;i<W*H;i++){
   if(data[i*ch+3]===0)continue;
   const x=i%W,y=(i/W)|0;
   let n=0,min=1e9;
   const ed=(j)=>{n++;const d=Math.abs(data[i*ch]-data[j*ch])+Math.abs(data[i*ch+1]-data[j*ch+1])+Math.abs(data[i*ch+2]-data[j*ch+2]);if(d<min)min=d;};
   if(x>0&&bg[i-1])ed(i-1);
   if(x<W-1&&bg[i+1])ed(i+1);
   if(y>0&&bg[i-W])ed(i-W);
   if(y<H-1&&bg[i+W])ed(i+W);
   if(n&&min<=120)data[i*ch+3]=128;
  }
 }
 let img=await sharp(data,{raw:{width:info.width,height:info.height,channels:4}}).resize(512,512,{fit:'contain',background:{r:0,g:0,b:0,alpha:0}}).png({compressionLevel:9,adaptiveFiltering:true}).toBuffer();
 let fmt='png';
 if(img.length>500*1024){
  fmt='webp';
  img=await sharp(img).webp({quality:80,alphaQuality:90}).toBuffer();
  if(img.length>500*1024)img=await sharp(img).webp({quality:60,alphaQuality:80}).toBuffer();
 }
 const up=await stickerApi.uploadStickerFile(userId,img,fmt);
 if(!up.ok)return reply('Gagal upload file stiker: '+(up.description||'unknown'));
 const one=JSON.stringify({sticker:up.result,format:'static',emoji_list:['✨']});
 const stickers='['+one+']';
 let add=await stickerApi.addStickerToSet(userId,setName,one);
 if(!add.ok){
  const cre=await stickerApi.createNewStickerSet(userId,setName,setTitle,stickers);
  if(!cre.ok&&!/already|exist/i.test(cre.description||''))return reply('Gagal membuat set stiker: '+(cre.description||'unknown'));
  if(cre.ok){
   return reply('✅ Stiker pertama dibuat di set baru:\n<a href="https://t.me/addstickers/'+setName+'">'+setTitle+'</a>\n\nBuka link untuk memasang set stiker.');
  }
  add=await stickerApi.addStickerToSet(userId,setName,one);
  if(!add.ok)return reply('Gagal menambahkan stiker: '+(add.description||'unknown'));
 }
 return reply('✅ Stiker ditambahkan ke set:\n<a href="https://t.me/addstickers/'+setName+'">'+setTitle+'</a>\n\nBuka link untuk memasang set stiker.');
}catch(e){
 return reply('Terjadi kesalahan: '+e.message);
}
